INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('00214f23-3d4e-4906-85c9-2154b1aeb858', 'STEP 1', '1.Initiate SSH connection to execute command remotely.
2.Retrieve the NATIVE_PLAYBACK_CHECK_AV_STATUS, NATIVE_PLAYBACK_MEDIAPLAYBACK_TIMEOUT and NATIVE_PLAYBACK_MEDIAPLAYBACK_SECOND_CHANNEL_TIMEOUT config values from Device config file.
3.Retrieve the video_src_url_mp4_360p and video_src_url_mp4_1080p  variable from MediaValidationVariables library
4.Construct the mediapipelinetests command based on the retrieved video url, testcasename, NATIVE_PLAYBACK_CHECK_AV_STATUS deviceconfig value and timeout
5.Execute the command in DUT. During the execution, the DUT will play with stream with HD content for NATIVE_PLAYBACK_MEDIAPLAYBACK_TIMEOUT and then switch to stream with SD content NATIVE_PLAYBACK_MEDIAPLAYBACK_SECOND_CHANNEL_TIMEOUT  seconds then application exits by closing the pipeline
6.Verify the output from the execute command and check if the strings "Failures: 0" and "Errors: 0", or "failed: 0" exists in the returned output
7.Based on the ExecuteCommand() return value and the output returned from the mediapipelinetests application, TM return SUCCESS/FAILURE status.', 'None', '3235dbd3-0373-4cb6-8444-d9a0c010f4cb', '2026-06-16 10:44:04.743973', '2026-06-16 10:44:04.743974');
DELETE FROM test_step WHERE script_id = 'bec24c1a-758c-4178-b9ae-a4304c0f5dcd';
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('617b36e3-af02-4170-8b43-d29f5d0bb921', 'TEST STEP 1', 'Load the sysutil and tdkbtr181 modules', 'The modules should be loaded successfully', 'bec24c1a-758c-4178-b9ae-a4304c0f5dcd', '2026-07-02 11:29:29.962484', '2026-07-02 11:29:29.962485');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('13a80d6f-1ba0-440b-89b0-7eb8d4d0bcbd', 'TEST STEP 2', 'Get the global IPv6 address of WAN interface', 'The IPv6 address should be available', 'bec24c1a-758c-4178-b9ae-a4304c0f5dcd', '2026-07-02 11:29:29.964300', '2026-07-02 11:29:29.964301');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('004cf070-c319-4f16-9a3d-18ff6b8a073f', 'TEST STEP 3', 'Reboot the DUT', 'The DUT should be rebooted successfully', 'bec24c1a-758c-4178-b9ae-a4304c0f5dcd', '2026-07-02 11:29:29.965290', '2026-07-02 11:29:29.965328');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('af2575a6-f282-41e3-a9db-9080d30c464b', 'TEST STEP 4', 'Check whether the global IPV6 address of WAN interface is available', 'The IPv6 Address should be available after reboot', 'bec24c1a-758c-4178-b9ae-a4304c0f5dcd', '2026-07-02 11:29:29.967386', '2026-07-02 11:29:29.967387');
