INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('6278f48d-0aba-4522-9de9-1d70a37069b3', 'Verify and activate required plugins', 'Check the activation state of the required plugins: org.rdk.DownloadManager, org.rdk.PackageManagerRDKEMS, and org.rdk.AppManager. Activate any that are not already in the activated state.
{"jsonrpc": "2.0", "id": 1234567890, "method": "Controller.1.status@<plugin_name>"}

{"jsonrpc": "2.0", "id": 1234567890, "method": "Controller.1.activate", "params": {"callsign": "<plugin_name>"}}', 'All three required plugins should be in activated state.', '82857b86-263a-4ac8-bb01-9a3ac246a740', '2026-07-01 10:04:40.263221', '2026-07-01 10:04:40.263222');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('e8204945-5557-4277-91b8-a5ecffb750b6', 'Install and launch the application', 'Check if com.rdkcentral.google is already installed. If not, download and install it via DownloadManager and PackageManagerRDKEMS, then launch it via AppManager.
{"jsonrpc": "2.0", "id": 1234567890, "method": "org.rdk.PackageManagerRDKEMS.1.listPackages"}

{"jsonrpc": "2.0", "id": 1234567890, "method": "org.rdk.DownloadManager.1.download", "params": {"url": "<app_download_url>/<google_bundle>"}}

{"jsonrpc": "2.0", "id": 1234567890, "method": "org.rdk.PackageManagerRDKEMS.install", "params": {"packageId": "com.rdkcentral.google", "version": "0.1.0", "additionalMetadata": [{"name": "type", "value": "native/dac-app"}], "fileLocator": "<PACKAGEMANAGER_FILE_LOCATOR>/package<download_id>"}}

{"jsonrpc": "2.0", "id": 1234567890, "method": "org.rdk.AppManager.launchApp", "params": {"appId": "com.rdkcentral.google", "intent": "", "launchArgs": ""}}', 'The application should be installed and launched successfully.', '82857b86-263a-4ac8-bb01-9a3ac246a740', '2026-07-01 10:04:40.268114', '2026-07-01 10:04:40.268115');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('9ada3de4-8398-4a65-b737-69e700250976', 'Validate resource usage before clearing app data', 'Measure and validate the system CPU and memory usage while the application is running, before the clearAppData operation. Invoke the DeviceInfo systeminfo API to retrieve current system metrics:
{"jsonrpc": "2.0", "id": 1234567890, "method": "DeviceInfo.1.systeminfo"}
Extract CPU load from the cpuload field and calculate memory usage using the formula (totalram - freeram) / totalram Ã— 100.', 'Resource usage (CPU and memory) should be within the expected limits.', '82857b86-263a-4ac8-bb01-9a3ac246a740', '2026-07-01 10:04:40.269980', '2026-07-01 10:04:40.269981');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('b508b6a8-abc0-4d7b-b806-e181923d57bc', 'Terminate the application', 'Terminate the running application before clearing app data.
{"jsonrpc": "2.0", "id": 1234567890, "method": "org.rdk.AppManager.terminateApp", "params": {"appId": "com.rdkcentral.google"}}', 'The application should terminate successfully.', '82857b86-263a-4ac8-bb01-9a3ac246a740', '2026-07-01 10:04:40.271970', '2026-07-01 10:04:40.271971');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('cad57570-cab0-4cfc-9264-4594cad82c26', 'Clear application data', 'Invoke the AppManager clearAppData API to clear all stored data for the application.
{"jsonrpc": "2.0", "id": 1234567890, "method": "org.rdk.AppManager.clearAppData", "params": {"appId": "com.rdkcentral.google"}}', 'The clearAppData request should return SUCCESS and all application data for com.rdkcentral.google should be cleared.', '82857b86-263a-4ac8-bb01-9a3ac246a740', '2026-07-01 10:04:40.272936', '2026-07-01 10:04:40.272937');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('0062c60a-9253-4c67-b944-c56b6418bfbc', 'Validate resource usage after clearing app data', 'Measure and validate the system CPU and memory usage again after the clearAppData operation. Invoke the DeviceInfo systeminfo API to retrieve current system metrics:
{"jsonrpc": "2.0", "id": 1234567890, "method": "DeviceInfo.1.systeminfo"}
Extract CPU load from the cpuload field and calculate memory usage using the formula (totalram - freeram) / totalram Ã— 100.', 'Resource usage (CPU and memory) should be within the expected limits after clearing app data. No unexpected resource spikes should be observed.', '82857b86-263a-4ac8-bb01-9a3ac246a740', '2026-07-01 10:04:40.273886', '2026-07-01 10:04:40.273887');
DELETE FROM test_step WHERE script_id = '1f109471-d81a-49ab-9a01-ec8a40da0999';
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('00854a03-f757-4752-9639-677c7adcac78', 'STEP 1', '1. As a pre requisite disable all other plugins and enable webkitinstance plugin.
2. Set the application URL
3. Play and pause the video from the application
3. Get the time taken to play/pause the video', 'The video must play and pause within expected range of ms.', '1f109471-d81a-49ab-9a01-ec8a40da0999', '2026-07-01 06:57:48.018634', '2026-07-01 06:57:48.018635');
