INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('00e4c2e1-1c60-48b2-9bec-a94a87d9862e', 'STEP 1', '1. Check the default interface of DUT and if it is not WIFI connect to WIFI.
2. Reboot the DUT using harakiri method.
3. Check whether WIFI connection is persisted.', 'WIFI connection should persist.', '3e5b11d3-4795-463d-9a67-779df7eae961', '2026-07-01 07:15:45.950913', '2026-07-01 07:15:45.950915');
