INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('20361773-36cd-40ae-9da8-860501dbb541', 'Create Display', 'Create WAYLAND_DISPLAY via RDKWindowManager.createDisplay and verify via RDKWindowManager.getApps', 'WAYLAND_DISPLAY named test must be created', 'e7dd4549-2a9a-425a-9f9d-868715d57b7b', '2026-06-23 06:17:18.999268', '2026-06-23 06:17:18.999270');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('4cd8c9c2-8b3a-4700-ac00-f0f063ebf979', 'Set environment', 'Set WAYLAND_DISPLAY to test and XDG_RUNTIME_DIR', 'WAYLAND_DISPLAY and XDG_RUNTIME_DIR must be successfully set', 'e7dd4549-2a9a-425a-9f9d-868715d57b7b', '2026-06-23 06:17:19.001131', '2026-06-23 06:17:19.001132');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('762b9eb4-7f0c-4f85-bf6c-21a691f981ce', 'Vulkan Graphics Pipeline Initialization', ' Initialize Vulkan instance with Wayland surface extensions, create Wayland surface, enumerate and select physical device with graphics capabilities, create logical device with graphics queue, setup swapchain with user-specified resolution, create render pass for color attachment, and allocate framebuffers for each swapchain image.', 'Vulkan instance created successfully, Wayland surface established, physical device selected with graphics queue family, logical device and swapchain initialized without errors, render pass and framebuffers created for specified resolution.

', 'e7dd4549-2a9a-425a-9f9d-868715d57b7b', '2026-06-23 06:17:19.002160', '2026-06-23 06:17:19.002161');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('02dda469-bb67-4f4f-be6b-a50b9a3bcbce', 'Ball Physics and Animation System Setup', 'Initialize ball physics arrays for position, velocity, and state tracking, setup animation parameters for bouncing ball mechanics with collision detection, configure ball count mode (constant 1 ball or increasing stress test), initialize random seed for ball positioning and movement patterns.', 'Ball physics system initialized with proper array allocations, animation parameters configured for realistic bouncing behavior, ball count mode set according to test configuration, random movement patterns established for dynamic animation.', 'e7dd4549-2a9a-425a-9f9d-868715d57b7b', '2026-06-23 06:17:19.003627', '2026-06-23 06:17:19.003629');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('a825349c-04f0-430c-8d79-90c03097972a', 'Multi-Layer Render Pass Recording', 'Record command buffers for each frame with background rendering (white clear color), animated ball drawing with variable sizes and colors, overlay notification rendering during 4-second cycles, implement dynamic render target switching between background and overlay content, optimize command buffer recording for layered content.', 'Command buffers recorded successfully with proper render pass structure, background and ball animation commands properly sequenced, overlay notification rendering integrated with timing control, multi-layer composition achieved without rendering artifacts.', 'e7dd4549-2a9a-425a-9f9d-868715d57b7b', '2026-06-23 06:17:19.004759', '2026-06-23 06:17:19.004760');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('6d3fa344-ef40-46b6-9f7d-bfdba5fd3bc2', 'Overlay Notification System Validation', 'xecute notification popup system with precise 4-second timing cycles (active during seconds 3-4, 7-8, etc.), render animated orange notification box with pulsing effects, implement segmented overlay rendering based on ball count, validate overlay appears and disappears correctly over animated background content.', 'Notification popups appear at exact 4-second intervals, orange overlay box renders with proper animation effects, segmented rendering matches ball count accurately, overlay visibility toggles correctly without affecting background animation timing.', 'e7dd4549-2a9a-425a-9f9d-868715d57b7b', '2026-06-23 06:17:19.005706', '2026-06-23 06:17:19.005707');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('89e57ac9-e309-418c-9c14-0bf2ed097ce2', 'Performance Monitoring and CSV Export', 'Monitor real-time FPS and CPU usage every second during test execution, track performance impact when overlay notifications are active versus inactive, calculate average statistics over test duration, export per-second performance data to CSV file with API, resolution, ball count, FPS, and CPU usage columns.', 'Performance monitoring captures accurate FPS and CPU metrics, overlay impact measured correctly (2-4% CPU increase during notification cycles), average statistics calculated properly, CSV export generates valid file with properly formatted performance data for analysis.', 'e7dd4549-2a9a-425a-9f9d-868715d57b7b', '2026-06-23 06:17:19.006638', '2026-06-23 06:17:19.006639');
DELETE FROM test_step WHERE script_id = 'fed26b9d-75e4-45b6-ae30-44f118d1c4b3';
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('0347b72a-c12a-4945-a702-1ae2a7183ae5', 'STEP 1', '1. Enable WebKitInstance plugin.
2. Set URL for keytest in WebKitInstance.
3. In a loop of minimum 15 iterations send a key using generatekey method of RDKShell to the system.
4. Validate the key press using logs from wpeframework logs.
5. Validate the time taken to get keys from RDK Shell.
6. Revert plugins status after completing the test', 'The time taken to get keys from RDK Shell must be within the expected limit', 'fed26b9d-75e4-45b6-ae30-44f118d1c4b3', '2026-07-01 07:11:42.581202', '2026-07-01 07:11:42.581204');
