INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('a317c63f-6b66-4a71-b800-5a0b8a1b2e9f', 'Verify and activate required plugins', 'Check the activation state of the required plugins: org.rdk.DownloadManager, org.rdk.PackageManagerRDKEMS, and org.rdk.AppManager. Activate any that are not already in the activated state.
{"jsonrpc": "2.0", "id": 1234567890, "method": "Controller.1.status@<plugin_name>"}

{"jsonrpc": "2.0", "id": 1234567890, "method": "Controller.1.activate", "params": {"callsign": "<plugin_name>"}}', 'All three required plugins should be in activated state.', '1ebf6000-2fc6-49e5-a700-a6cb5c908765', '2026-07-01 10:04:40.516109', '2026-07-01 10:04:40.516111');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('0394c388-4785-4670-800b-4993b5f852c5', 'Install the application without launching', 'Check if com.rdkcentral.google is already installed. If not, download and install it via DownloadManager and PackageManagerRDKEMS without launching it (launch=False).
{"jsonrpc": "2.0", "id": 1234567890, "method": "org.rdk.PackageManagerRDKEMS.1.listPackages"}

{"jsonrpc": "2.0", "id": 1234567890, "method": "org.rdk.DownloadManager.1.download", "params": {"url": "<app_download_url>/<google_bundle>"}}

{"jsonrpc": "2.0", "id": 1234567890, "method": "org.rdk.PackageManagerRDKEMS.install", "params": {"packageId": "com.rdkcentral.google", "version": "0.1.0", "additionalMetadata": [{"name": "type", "value": "native/dac-app"}], "fileLocator": "<PACKAGEMANAGER_FILE_LOCATOR>/package<download_id>"}}', 'The application should be installed successfully without being launched.', '1ebf6000-2fc6-49e5-a700-a6cb5c908765', '2026-07-01 10:04:40.518078', '2026-07-01 10:04:40.518080');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('12c2efa9-b5c4-4e93-a434-2938a681deb2', 'Launch the application (First Launch)', 'Launch the application via the AppManager. Wait 10 seconds after launch to allow the application to reach a stable state.
{"jsonrpc": "2.0", "id": 1234567890, "method": "org.rdk.AppManager.launchApp", "params": {"appId": "com.rdkcentral.google", "intent": "", "launchArgs": ""}}', 'The application should launch successfully and reach APP_STATE_ACTIVE.', '1ebf6000-2fc6-49e5-a700-a6cb5c908765', '2026-07-01 10:04:40.519258', '2026-07-01 10:04:40.519259');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('dea8fc39-c9fc-490d-8a0b-c7404ea0fc5f', 'Validate resource usage after first launch', 'Measure and validate the system CPU and memory usage after the first launch. Invoke the DeviceInfo systeminfo API to retrieve current system metrics:
{"jsonrpc": "2.0", "id": 1234567890, "method": "DeviceInfo.1.systeminfo"}
Extract CPU load from the cpuload field and calculate memory usage using the formula (totalram - freeram) / totalram Ã— 100.', 'Resource usage (CPU and memory) should be within the expected limits after the first launch.', '1ebf6000-2fc6-49e5-a700-a6cb5c908765', '2026-07-01 10:04:40.520323', '2026-07-01 10:04:40.520324');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('713104fa-0b26-4bf4-a633-b5d20a88210c', 'Kill the application', 'Send a killApp request to the AppManager to forcefully kill the running application. Wait 5 seconds to allow the kill to complete before relaunching.
{"jsonrpc": "2.0", "id": 1234567890, "method": "org.rdk.AppManager.killApp", "params": {"appId": "com.rdkcentral.google"}}', 'The killApp request should return SUCCESS and the application should be killed.', '1ebf6000-2fc6-49e5-a700-a6cb5c908765', '2026-07-01 10:04:40.521713', '2026-07-01 10:04:40.521714');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('3f748b8f-c9d0-4f5b-a979-9ea4ab00ca42', 'Relaunch the application (Second Launch)', 'Launch the application again via the AppManager. Wait 10 seconds after launch to allow the application to reach a stable state.
{"jsonrpc": "2.0", "id": 1234567890, "method": "org.rdk.AppManager.launchApp", "params": {"appId": "com.rdkcentral.google", "intent": "", "launchArgs": ""}}', 'The application should relaunch successfully and reach APP_STATE_ACTIVE.', '1ebf6000-2fc6-49e5-a700-a6cb5c908765', '2026-07-01 10:04:40.523573', '2026-07-01 10:04:40.523574');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('e40c7875-75cb-4b6a-b3d4-e0aca9340325', 'Validate resource usage after second launch', 'Measure and validate the system CPU and memory usage after the second (relaunch) launch. Invoke the DeviceInfo systeminfo API to retrieve current system metrics:
{"jsonrpc": "2.0", "id": 1234567890, "method": "DeviceInfo.1.systeminfo"}
Extract CPU load from the cpuload field and calculate memory usage using the formula (totalram - freeram) / totalram Ã— 100.', 'Resource usage (CPU and memory) should be within the expected limits after the second launch. No resource leaks or unexpected spikes should be observed compared to the first launch.', '1ebf6000-2fc6-49e5-a700-a6cb5c908765', '2026-07-01 10:04:40.524634', '2026-07-01 10:04:40.524635');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('bf93856e-618e-4901-9b15-41fc558aed2d', 'Terminate the application', 'Terminate the running application after resource measurement.
{"jsonrpc": "2.0", "id": 1234567890, "method": "org.rdk.AppManager.terminateApp", "params": {"appId": "com.rdkcentral.google"}}', 'The application should terminate successfully.', '1ebf6000-2fc6-49e5-a700-a6cb5c908765', '2026-07-01 10:04:40.525550', '2026-07-01 10:04:40.525551');
