INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('046be499-a4a0-4826-bc2e-f515406f997f', 'Test Step 1', 'Get plugin status, set DeviceInfo and org.rdk.PersistentStore to "activated", wait 20 seconds for initialization.', 'Required plugins activated (DeviceInfo: activated, org.rdk.PersistentStore: activated)', '341c19f9-70d4-497a-9e83-aa2da7e1104f', '2026-07-01 07:03:27.553703', '2026-07-01 07:03:27.553704');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('59db59ea-d07d-4375-ad6b-4687e98039e9', 'Test Step 2', 'Retrieve Vorbis video URL, build test parameters (type, autotest, operations=[play/pause 10s each]), set URL in PersistentStore, download/install/launch unified player app.', 'Video URL set in PersistentStore, app downloaded/installed/launched successfully', '341c19f9-70d4-497a-9e83-aa2da7e1104f', '2026-07-01 07:03:27.554604', '2026-07-01 07:03:27.554605');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('a7a11af0-69c7-4b29-9cc1-cbfde663eb34', 'Test Step 3', 'Create event listener, send play command, capture expected/observed play timestamps, send pause command, capture expected/observed pause timestamps.', 'All four event timestamps captured (Expected Pause, Observed Pause, Expected Play, Observed Play) with valid UTC times', '341c19f9-70d4-497a-9e83-aa2da7e1104f', '2026-07-01 07:03:27.555295', '2026-07-01 07:03:27.555295');
