INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('ffe670a4-e0e2-4879-a824-0977343746ba', 'Test Step 1', 'Verify AI Manager plugins (DownloadManager, PackageManagerRDKEMS, AppManager, SystemServices) availability, activate required plugins, and assess baseline system stability across all components', 'All required plugins activated successfully and baseline system stability confirmed (PackageManager, AppManager, SystemServices responsive)', '7bb16e42-04f5-4a26-8f1b-63a6f5506d2b', '2026-07-01 06:21:04.329564', '2026-07-01 06:21:04.329565');
