INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('59e14251-87f2-4367-8856-f6c45322b061', 'Test Step 3', 'Attempt to install the already-installed app multiple times (default: 3 attempts) using PackageManagerRDKEMS.install, track responses, errors, and system behavior', 'All duplicate installation attempts processed with appropriate responses (acceptance/rejection) tracked', '7bb16e42-04f5-4a26-8f1b-63a6f5506d2b', '2026-07-01 06:21:04.333114', '2026-07-01 06:21:04.333115');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('dcc95b34-003b-4808-acd9-e4a78bdb1248', 'Test Step 4', 'Monitor onAppInstalled events for 30 seconds, check for duplicate app entries in installed apps list, and analyze system response patterns', 'Events monitored and duplicate entry detection performed, response patterns analyzed', '7bb16e42-04f5-4a26-8f1b-63a6f5506d2b', '2026-07-01 06:21:04.334515', '2026-07-01 06:21:04.334516');
