INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('e9e2b7df-8cb9-41bd-80d2-85461b4cabb0', 'STEP 4', 'Check if the uptime is greater than Wait Time else sleep until the wait time is reached.', 'Device comes up after factory reset within the expected uptime', 'c7043005-b79e-4e17-8c4e-9785313440d3', '2026-07-02 09:01:00.203582', '2026-07-02 09:01:00.203583');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('e40eb870-5abf-4fc6-9a33-f5c7b64dbcd6', 'STEP 5', 'Check if the main interfaces are up and running.', 'All interfaces should be up', 'c7043005-b79e-4e17-8c4e-9785313440d3', '2026-07-02 09:01:00.204511', '2026-07-02 09:01:00.204512');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('1ac152f0-d049-41fd-87a1-19856d0c687c', 'STEP 6', 'Check whether critical processes are up after the factory reset.', 'All the critical processes should be up and running once the devices comes up after factory reset within the expected uptime', 'c7043005-b79e-4e17-8c4e-9785313440d3', '2026-07-02 09:01:00.205552', '2026-07-02 09:01:00.205553');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('3f8a75bd-8b63-4ceb-99f0-f18bd9f6cb63', 'STEP 7', 'Do factory reset and device health check for configurable parameter TOTAL_ITERATIONS times .', 'Factory reset and device health check should be successful', 'c7043005-b79e-4e17-8c4e-9785313440d3', '2026-07-02 09:01:00.206474', '2026-07-02 09:01:00.206475');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('17c9148e-179e-4a0c-b7a8-388e9b4b9c88', 'STEP 8', 'If failed, stop the test on first failure after artifact upload.', 'Artifact upload should be successful', 'c7043005-b79e-4e17-8c4e-9785313440d3', '2026-07-02 09:01:00.207362', '2026-07-02 09:01:00.207363');
