INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('9ae18f98-4d05-49a4-b01a-f007fa5f46de', 'Verify and activate required plugins', 'Check the activation state of the required plugins: org.rdk.DownloadManager, org.rdk.PackageManagerRDKEMS, and org.rdk.AppManager. Activate any that are not already in the activated state.
{"jsonrpc": "2.0", "id": 1234567890, "method": "Controller.1.status@<plugin_name>"}

{"jsonrpc": "2.0", "id": 1234567890, "method": "Controller.1.activate", "params": {"callsign": "<plugin_name>"}}', 'All three required plugins should be in activated state.', 'c13d411a-bc8c-4fd3-9561-e820b8e93ddc', '2026-07-01 10:04:40.459633', '2026-07-01 10:04:40.459634');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('0ac2579a-de34-42d4-b42e-cc745a3557bc', 'Install the application without launching', 'Check if com.rdkcentral.google is already installed. If not, download and install it via DownloadManager and PackageManagerRDKEMS. The application is not launched at this stage (launch=False).
{"jsonrpc": "2.0", "id": 1234567890, "method": "org.rdk.PackageManagerRDKEMS.1.listPackages"}

{"jsonrpc": "2.0", "id": 1234567890, "method": "org.rdk.DownloadManager.1.download", "params": {"url": "<app_download_url>/<google_bundle>"}}

{"jsonrpc": "2.0", "id": 1234567890, "method": "org.rdk.PackageManagerRDKEMS.install", "params": {"packageId": "com.rdkcentral.google", "version": "0.1.0", "additionalMetadata": [{"name": "type", "value": "native/dac-app"}], "fileLocator": "<PACKAGEMANAGER_FILE_LOCATOR>/package<download_id>"}}', 'The application should be installed successfully and appear in the installed packages list. The app is not yet launched.', 'c13d411a-bc8c-4fd3-9561-e820b8e93ddc', '2026-07-01 10:04:40.461186', '2026-07-01 10:04:40.461187');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('4359dbf4-5d5e-4d10-bf01-fc769e1d877c', 'Subscribe to lifecycle state change event', 'Register a WebSocket event listener on the Thunder JSON-RPC endpoint for onAppLifecycleStateChanged. Wait 5 seconds after registration to ensure the listener is ready before the launch is triggered.
{"jsonrpc": "2.0", "id": 9, "method": "org.rdk.AppManager.1.register", "params": {"event": "onAppLifecycleStateChanged", "id": "client.events.1"}}', 'Event subscription should be established successfully.', 'c13d411a-bc8c-4fd3-9561-e820b8e93ddc', '2026-07-01 10:04:40.462351', '2026-07-01 10:04:40.462352');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('205ffce8-4eb4-4db3-92c8-43d644675a58', 'Trigger launchApp and record start time', 'Record the current UTC timestamp as the launch start time, then send the launchApp request to the AppManager.
{"jsonrpc": "2.0", "id": 1234567890, "method": "org.rdk.AppManager.launchApp", "params": {"appId": "com.rdkcentral.google", "intent": "", "launchArgs": ""}}', 'The launchApp request should be accepted and return SUCCESS.', 'c13d411a-bc8c-4fd3-9561-e820b8e93ddc', '2026-07-01 10:04:40.463399', '2026-07-01 10:04:40.463400');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('4acf6c08-08a1-4265-af62-5890bb42d905', 'Monitor event buffer for launch lifecycle events', 'Monitor the onAppLifecycleStateChanged event buffer for up to 120 seconds. Record the timestamp of each event as it arrives: APP_STATE_LOADING, APP_STATE_INITIALIZING, APP_STATE_PAUSED, and APP_STATE_ACTIVE. The loop exits when APP_STATE_ACTIVE is received.', 'All four launch lifecycle events should be received within the timeout period.', 'c13d411a-bc8c-4fd3-9561-e820b8e93ddc', '2026-07-01 10:04:40.464454', '2026-07-01 10:04:40.464456');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('f1794b8f-fb83-4a1f-84ad-ca5af60cd495', 'Verify all launch lifecycle states received', 'Confirm that all four expected lifecycle state transitions were received: APP_STATE_LOADING, APP_STATE_INITIALIZING, APP_STATE_PAUSED, and APP_STATE_ACTIVE for com.rdkcentral.google.
Example event: {"jsonrpc": "2.0", "method": "client.events.1.onAppLifecycleStateChanged", "params": {"appId": "com.rdkcentral.google", "newState": "APP_STATE_ACTIVE", "oldState": "APP_STATE_PAUSED", "errorReason": "APP_ERROR_NONE"}}', 'All four launch lifecycle state transitions should be confirmed for the application.', 'c13d411a-bc8c-4fd3-9561-e820b8e93ddc', '2026-07-01 10:04:40.465347', '2026-07-01 10:04:40.465348');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('578e58b0-011f-4b50-86e0-7929b874e14b', 'Calculate transition times and validate against threshold', 'Compute the elapsed time in milliseconds for each transition: launch start â†’ APP_STATE_LOADING, APP_STATE_LOADING â†’ APP_STATE_INITIALIZING, APP_STATE_INITIALIZING â†’ APP_STATE_PAUSED, APP_STATE_PAUSED â†’ APP_STATE_ACTIVE, and total launch start â†’ APP_STATE_ACTIVE. Compare each against APPMANAGER_LAUNCH_EVENT_THRESHOLD_VALUE + THRESHOLD_OFFSET from device config.', 'Each individual transition time and the total launch time should be within the range: 0 < time < (APPMANAGER_LAUNCH_EVENT_THRESHOLD_VALUE + THRESHOLD_OFFSET) milliseconds.', 'c13d411a-bc8c-4fd3-9561-e820b8e93ddc', '2026-07-01 10:04:40.466430', '2026-07-01 10:04:40.466431');
DELETE FROM test_step WHERE script_id = '112f6411-c695-469f-b76b-6b8e1848387c';
