INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('86628aee-3d69-412e-a48e-87d1d478fcbb', 'Test step 1', ' Register for AI Manager events (onAppLifecycleStateChanged, onAppDownloadStatus, onAppInstalled, onAppUninstalled) and perform baseline system stability assessment', 'Event listener registered successfully and all baseline stability checks return SUCCESS status', '82f2879b-1f0a-445e-8393-4c53417cf6ef', '2026-07-01 06:39:44.791679', '2026-07-01 06:39:44.791680');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('ce9ec426-fc54-44a5-9485-8ea457bc5efa', 'Test Step 2', 'Check target application installation status and install app if not present (download using DownloadManager and install using PackageManagerRDKEMS) ', 'Target app successfully installed and available for launch with installation completion events received', '82f2879b-1f0a-445e-8393-4c53417cf6ef', '2026-07-01 06:39:44.793480', '2026-07-01 06:39:44.793481');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('b5649853-9a5c-423d-bd12-99dc4e998518', 'Test Step 3', ' Save current system time, launch target application using launchApp API, and verify app reaches launched/running state', 'App successfully launched and stabilized in running/active state within timeout', '82f2879b-1f0a-445e-8393-4c53417cf6ef', '2026-07-01 06:39:44.794397', '2026-07-01 06:39:44.794398');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('a5e06c22-51b0-4544-a6d8-84ce3bc3af1b', 'Test Step 4', 'Save current system time and execute uninstall command for the actively running application using PackageManagerRDKEMS uninstall API', 'Uninstall command returns SUCCESS response for actively running application', '82f2879b-1f0a-445e-8393-4c53417cf6ef', '2026-07-01 06:39:44.795578', '2026-07-01 06:39:44.795579');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('c83f330f-f862-43f4-9771-72dcfeb5270a', 'Test Step 5', 'Wait for onAppUninstalled or lifecycle termination events, capture completion time, and calculate total uninstall duration', 'App uninstall completion event received within timeout and uninstall time calculated successfully', '82f2879b-1f0a-445e-8393-4c53417cf6ef', '2026-07-01 06:39:44.796561', '2026-07-01 06:39:44.796562');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('0c975c34-2483-4338-adbd-b35d1ebad39c', 'Test Step 6', 'Perform comprehensive post-uninstall stability assessment, verify app listing functionality, confirm app removal, and validate overall test success ', 'All post-stress stability checks return SUCCESS, app removed from installed list, and system remains stable throughout operation', '82f2879b-1f0a-445e-8393-4c53417cf6ef', '2026-07-01 06:39:44.797579', '2026-07-01 06:39:44.797580');
