INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('0d59c395-be5b-4075-a2a2-42e6c91e88e7', 'Test Step 1', 'Verify App Manager plugins (DownloadManager, PackageManagerRDKEMS, AppManager) availability, activate required plugins, and validate configuration parameters (app URL, app ID, load threshold values)', 'All required plugins activated successfully and configuration parameters retrieved', 'b8423544-448b-44f6-99d9-23e61f6686e9', '2026-07-01 06:30:20.178546', '2026-07-01 06:30:20.178547');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('cf6b86db-c740-4a52-8c4b-75f3b3d993a1', 'Test Step 2', 'Compare  time against configured threshold (APP_LOAD_THRESHOLD_VALUE + THRESHOLD_OFFSET) and generate summary report with all timing metrics', 'Time validated as within acceptable range (PASS) or exceeds threshold (FAIL)', 'b8423544-448b-44f6-99d9-23e61f6686e9', '2026-07-01 06:30:20.179377', '2026-07-01 06:30:20.179378');
