INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('2ba62150-37e6-4967-9502-0b6b5baab16c', 'STEP 1', '1.Initiate SSH connection to execute command remotely.
