INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('32a89a85-5242-489f-acf5-4b49f12a193d', 'STEP 1', '1. Connect WiFi with lightning app to detect ip change loaded.
2. Launch the lightning app and capture the time taken for launching the app with WiFi
3. Validate the time taken to launch with threshold value
