INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('a085e496-b802-4764-ac04-d4f45c7cc0c7', 'Verify and activate required plugins', 'Check the activation state of the required plugins: org.rdk.DownloadManager, org.rdk.PackageManagerRDKEMS, and org.rdk.AppManager. Activate any that are not already in the activated state.
{"jsonrpc": "2.0", "id": 1234567890, "method": "Controller.1.status@<plugin_name>"}

{"jsonrpc": "2.0", "id": 1234567890, "method": "Controller.1.activate", "params": {"callsign": "<plugin_name>"}}', 'All three required plugins should be in activated state.', 'd389bda0-dde2-4412-8305-4c6c28f54c19', '2026-07-01 10:04:40.346188', '2026-07-01 10:04:40.346189');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('917c5f4a-7029-42d1-a21b-22f1b25f6247', 'Install and launch the application', 'Check if com.rdkcentral.google is already installed. If not, download and install it via DownloadManager and PackageManagerRDKEMS, then launch it via AppManager. Wait 10 seconds after launch to allow the application to reach a stable state.
{"jsonrpc": "2.0", "id": 1234567890, "method": "org.rdk.PackageManagerRDKEMS.1.listPackages"}

{"jsonrpc": "2.0", "id": 1234567890, "method": "org.rdk.DownloadManager.1.download", "params": {"url": "<app_download_url>/<google_bundle>"}}

{"jsonrpc": "2.0", "id": 1234567890, "method": "org.rdk.PackageManagerRDKEMS.install", "params": {"packageId": "com.rdkcentral.google", "version": "0.1.0", "additionalMetadata": [{"name": "type", "value": "native/dac-app"}], "fileLocator": "<PACKAGEMANAGER_FILE_LOCATOR>/package<download_id>"}}

{"jsonrpc": "2.0", "id": 1234567890, "method": "org.rdk.AppManager.launchApp", "params": {"appId": "com.rdkcentral.google", "intent": "", "launchArgs": ""}}', 'The application should be installed and launched successfully and reach APP_STATE_ACTIVE.', 'd389bda0-dde2-4412-8305-4c6c28f54c19', '2026-07-01 10:04:40.347741', '2026-07-01 10:04:40.347742');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('8859def8-554f-4e14-9932-27596af4ed78', 'Kill the application', 'Send a killApp request to the AppManager to forcefully kill the running application.
