INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('671cb8b4-5b27-467a-8f8c-f0af95f4befc', 'Validate resource usage after killing the app', 'Measure and validate the system CPU and memory usage after the application has been killed. Invoke the DeviceInfo systeminfo API to retrieve current system metrics:
