INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('a723b676-4636-49fe-a77c-ce7e8c978f71', 'Retrieve the app instance ID', 'Query the loaded apps list and extract the appInstanceId for com.rdkcentral.google in APP_STATE_ACTIVE state. This instance ID is required as the client identifier for the RDKWindowManager setVisible call.
{"jsonrpc": "2.0", "id": 1234567890, "method": "org.rdk.AppManager.getLoadedApps"}', 'The appInstanceId should be retrieved successfully for the active application instance.', 'a962c8a7-b90a-4a08-80ef-95b83385c22d', '2026-07-01 10:04:40.757367', '2026-07-01 10:04:40.757368');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('83ddc6b6-3cbb-4e0a-b734-70f744e83fa3', 'Subscribe to the onHidden event', 'Register a WebSocket event listener on the Thunder JSON-RPC endpoint for the onHidden event from org.rdk.RDKWindowManager. Wait 3 seconds after registration.
{"jsonrpc": "2.0", "id": 9, "method": "org.rdk.RDKWindowManager.1.register", "params": {"event": "onHidden", "id": "client.events.1"}}', 'The onHidden event subscription should be established successfully.', 'a962c8a7-b90a-4a08-80ef-95b83385c22d', '2026-07-01 10:04:40.758395', '2026-07-01 10:04:40.758397');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('d95d4081-8a02-4b94-aa49-d52abcf60e7c', 'Trigger setVisible(false) and record start time', 'Record the current UTC timestamp as the start time, then call org.rdk.RDKWindowManager.setVisible with visible=false for the retrieved appInstanceId.
{"jsonrpc": "2.0", "id": 1234567890, "method": "org.rdk.RDKWindowManager.1.setVisible", "params": {"client": "<appInstanceId>", "visible": false}}', 'The setVisible request should be accepted successfully.', 'a962c8a7-b90a-4a08-80ef-95b83385c22d', '2026-07-01 10:04:40.759477', '2026-07-01 10:04:40.759478');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('7c938a04-8621-4b0c-88e6-0ffb5785d9a6', 'Wait for the onHidden event', 'Monitor the event buffer for up to 120 seconds until the onHidden event containing the appInstanceId is received. Record the event timestamp.', 'The onHidden event should be received for the application instance within the timeout period.', 'a962c8a7-b90a-4a08-80ef-95b83385c22d', '2026-07-01 10:04:40.760443', '2026-07-01 10:04:40.760444');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('ffe43fb5-719d-4eb7-83fd-a9ff69e0366c', 'Calculate hide time and validate against threshold', 'Compute the elapsed time in milliseconds as the difference between the onHidden event timestamp and the recorded setVisible start time. Compare against APPMANAGER_SET_VISIBLE_THRESHOLD_VALUE + THRESHOLD_OFFSET from device config.', 'The time taken to receive the onHidden event should be within the range: 0 < time < (APPMANAGER_SET_VISIBLE_THRESHOLD_VALUE + THRESHOLD_OFFSET) milliseconds.', 'a962c8a7-b90a-4a08-80ef-95b83385c22d', '2026-07-01 10:04:40.762229', '2026-07-01 10:04:40.762230');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('67ccb7f7-e953-45be-aa76-8bb404b9fac0', 'Terminate the application', 'Terminate the running application using the AppManager terminateApp API.
{"jsonrpc": "2.0", "id": 1234567890, "method": "org.rdk.AppManager.terminateApp", "params": {"appId": "com.rdkcentral.google"}}', 'The application should terminate successfully.', 'a962c8a7-b90a-4a08-80ef-95b83385c22d', '2026-07-01 10:04:40.763199', '2026-07-01 10:04:40.763201');
